-- global/0001_init.sql: consolidated end-state schema for the global database (ADR-0049).
-- Generated by wipe-and-adopt from the legacy 45-migration history; no data migration.

CREATE TABLE audit_events (
    seq       INTEGER PRIMARY KEY,
    time      TEXT NOT NULL,
    actor     TEXT NOT NULL,
    action    TEXT NOT NULL,
    target    TEXT NOT NULL DEFAULT '',
    data      TEXT NOT NULL DEFAULT '',
    prev_hash TEXT NOT NULL DEFAULT '',
    hash      TEXT NOT NULL
);;

CREATE TABLE canaries (
    id         TEXT PRIMARY KEY,
    label      TEXT NOT NULL,
    token      TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);;

CREATE TABLE dlp_events (
    id         TEXT PRIMARY KEY,
    kind       TEXT NOT NULL,   -- secret | canary | pattern
    label      TEXT NOT NULL,
    action     TEXT NOT NULL,   -- block | alert
    blocked    INTEGER NOT NULL DEFAULT 0,
    location   TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL
);;

CREATE TABLE groups (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name            TEXT NOT NULL,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);;

CREATE TABLE "kb_entries" (
    id              TEXT PRIMARY KEY,
    scope           TEXT NOT NULL DEFAULT 'target' CHECK (scope IN ('target', 'group', 'org', 'global')),
    target_id       TEXT REFERENCES targets(id) ON DELETE CASCADE,
    group_id        TEXT REFERENCES groups(id) ON DELETE CASCADE,
    organization_id TEXT REFERENCES organizations(id) ON DELETE CASCADE,
    kind            TEXT NOT NULL,
    title           TEXT NOT NULL,
    body            TEXT NOT NULL DEFAULT '',
    tags            TEXT NOT NULL DEFAULT '',
    sensitivity     TEXT NOT NULL DEFAULT 'private' CHECK (sensitivity IN ('open_source', 'private')),
    origin          TEXT NOT NULL DEFAULT 'human' CHECK (origin IN ('human', 'thread', 'derived')),
    review_state    TEXT NOT NULL DEFAULT 'unreviewed' CHECK (review_state IN ('unreviewed', 'confirmed', 'rejected')),
    source_ref      TEXT NOT NULL DEFAULT '',
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL, last_verified_at TEXT,
    -- exactly the anchor for the scope is set (global anchors to nothing).
    CHECK (
        (scope = 'target' AND target_id IS NOT NULL AND group_id IS NULL AND organization_id IS NULL) OR
        (scope = 'group'  AND group_id  IS NOT NULL AND target_id IS NULL AND organization_id IS NULL) OR
        (scope = 'org'    AND organization_id IS NOT NULL AND target_id IS NULL AND group_id IS NULL) OR
        (scope = 'global' AND target_id IS NULL AND group_id IS NULL AND organization_id IS NULL)
    )
);;

CREATE TABLE organizations (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);;

CREATE TABLE providers (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    type       TEXT NOT NULL,               -- anthropic | openai | ollama | claude-cli | mock | …
    model      TEXT NOT NULL DEFAULT '',
    base_url   TEXT NOT NULL DEFAULT '',
    key_sealed TEXT NOT NULL DEFAULT '',     -- vault-sealed credential; empty for keyless providers
    created_at TEXT NOT NULL
);;

CREATE TABLE runner_enroll_tokens (
    token_hash TEXT PRIMARY KEY,                       -- sha256(token) hex; the token is shown once to the operator
    label      TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    used_at    TEXT                                    -- set when consumed; NULL = still valid
);;

CREATE TABLE runners (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    pubkey      TEXT NOT NULL,                         -- base64 ed25519 public key (authenticates the runner)
    status      TEXT NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'revoked')),
    enrolled_at TEXT NOT NULL,
    last_seen   TEXT
);;

CREATE TABLE saved_playbooks (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    goal        TEXT NOT NULL DEFAULT '',
    steps       TEXT NOT NULL,
    source      TEXT NOT NULL DEFAULT '', -- e.g. "plan:<id>" when recorded from a run
    created_at  TEXT NOT NULL
);;

CREATE TABLE saved_profiles (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    persona     TEXT NOT NULL,
    tools       TEXT NOT NULL,
    created_at  TEXT NOT NULL
);;

CREATE TABLE secrets (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    sealed     TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);;

CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL
);;

CREATE TABLE targets (
    id              TEXT PRIMARY KEY,
    organization_id TEXT REFERENCES organizations(id) ON DELETE SET NULL,
    name            TEXT NOT NULL,
    description     TEXT NOT NULL DEFAULT '',
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);;

CREATE INDEX idx_dlp_events_time ON dlp_events(created_at);;

CREATE INDEX idx_groups_organization ON groups(organization_id);;

CREATE INDEX idx_kb_group ON kb_entries(group_id);;

CREATE INDEX idx_kb_org ON kb_entries(organization_id);;

CREATE INDEX idx_kb_scope ON kb_entries(scope);;

CREATE INDEX idx_kb_target ON kb_entries(target_id);;

CREATE INDEX idx_targets_organization ON targets(organization_id);;

-- project_index: a denormalized directory of projects (ADR-0049). The authoritative project row lives in
-- each projects/<id>/project.db; this index lets cross-project listing/dashboards read one place instead of
-- fanning out across every per-project database. Maintained on project create/update/purge.
CREATE TABLE project_index (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL DEFAULT '',
    status     TEXT NOT NULL DEFAULT 'active',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
